action.command:
cat << 'EOF' | php
<?php
$message = json_decode(file_get_contents('php://stdin'), true)['userMessage'] ?? '';
$testKeywords = ['test', 'testing', 'new feature', 'significant feature'];
$shouldTest = false;

foreach ($testKeywords as $keyword) {
    if (stripos($message, $keyword) !== false) {
        $shouldTest = true;
        break;
    }
}

if ($shouldTest) {
    echo json_encode([
        'hookSpecificOutput' => [
            'permissionDecision' => 'ask',
            'permissionDecisionReason' => 'Testing workflow detected. Ready to: 1) Set DB_HOST to postgres in .env, 2) Run podman-compose up --build -d, 3) Run docker exec <app-container> php artisan test'
        ]
    ]);
    exit(0);
} else {
    exit(1);
}
EOF
